-- Dumping data for table rpp_ai.dalils: ~2 rows (approximately)
INSERT INTO `dalils` (`id`, `name`, `source`, `source_name`, `translation`, `meaning`, `image_path`) VALUES
	(1, 'operasi matematika : pengurangan', 'Al-Quran', 'Q.S. Al-‘Ankabuut : 14', 'Sungguh, Kami benar-benar telah mengutus Nuh kepada kaumnya, lalu dia tinggal bersama mereka selama seribu tahun kurang lima puluh tahun. Kemudian, mereka dilanda banjir besar dalam keadaan sebagai orang-orang zalim.', 'Ayat di atas menjelaskan tentang lamanya Nabi Nuh ‘alaihissalam tinggal bersama kaumnya, yaitu 1000 tahun dikurang 50 tahun, alias 950 tahun lamanya. (pengurangan)', '1784522149_Screenshot 2026-07-20 113404.png'),
	(2, 'investasi', 'Al-Quran', 'QS. Al-Baqarah Ayat 261', 'Perumpamaan orang-orang yang menginfakkan hartanya di jalan Allah adalah seperti (orang-orang yang menabur) sebutir biji (benih) yang menumbuhkan tujuh tangkai, pada setiap tangkai ada seratus biji. Allah melipatgandakan (pahala) bagi siapa yang Dia kehendaki. Allah Mahaluas lagi Maha Mengetahui.', 'Allah beralih menjelaskan permisalan terkait balasan yang berlipat ganda bagi orang yang berinfak di jalan Allah. Perumpamaan keadaan yang sangat mengagumkan dari orang yang menginfakkan hartanya di jalan Allah dengan tulus untuk ketaatan dan kebaikan, seperti keadaan seorang petani yang menabur benih. Sebutir biji yang ditanam di tanah yang subur menumbuhkan tujuh tangkai, pada setiap tangkai ada seratus biji sehingga jumlah keseluruhannya menjadi tujuh ratus. Bahkan Allah terus melipatgandakan pahala kebaikan sampai tujuh ratus kali lipat atau lebih bagi siapa yang Dia kehendaki sesuai tingkat keimanan dan keikhlasan hati yang berinfak. Dan jangan menduga Allah tidak mampu memberi sebanyak mungkin, sebab Allah Mahaluas karunia-Nya. Dan jangan menduga Dia tidak tahu siapa yang berinfak di jalan-Nya dengan tulus, sebab Dia Maha Mengetahui siapa yang berhak menerima karunia tersebut, dan Maha Mengetahui atas segala niat hamba-Nya.', '1784688106_Screenshot 2026-07-22 094041.png');

